module.exports = async ({ core }) => {
  const { VERSION_MANIFEST, GITHUB_REPOSITORY_OWNER, IMAGE_REPOSITORY_NAME } =
    process.env

  if (!VERSION_MANIFEST) {
    core.setFailed('Environment variable VERSION_MANIFEST is required.')
    return false
  }

  if (!GITHUB_REPOSITORY_OWNER) {
    core.setFailed('Environment variable GITHUB_REPOSITORY_OWNER is required.')
    return false
  }

  if (!IMAGE_REPOSITORY_NAME) {
    core.setFailed('Environment variable IMAGE_REPOSITORY_NAME is required.')
    return false
  }

  const fs = require('fs')
  const text = fs.readFileSync(VERSION_MANIFEST, 'utf8')
  const data = JSON.parse(text)

  // Backstop only. config/schema.cue is the real guard and also checks semver
  // shapes, but runs in a separate step — these throws are the last chance
  // before a bad value becomes a build arg.
  const isBlank = (value) =>
    value === undefined || value === null || value === ''

  const read = (path) => {
    const value = path
      .split('.')
      .reduce((node, key) => (node == null ? node : node[key]), data)

    if (isBlank(value)) {
      throw new Error(`${VERSION_MANIFEST} has no value at '${path}'.`)
    }

    return value
  }

  const readPlatformVersions = () => {
    const platforms = read('android.platforms')

    if (!Array.isArray(platforms) || platforms.length === 0) {
      throw new Error(
        `${VERSION_MANIFEST} needs a non-empty array at 'android.platforms'.`
      )
    }

    return platforms
      .map((platform, index) => {
        if (isBlank(platform?.version)) {
          throw new Error(
            `${VERSION_MANIFEST} has no value at 'android.platforms[${index}].version'.`
          )
        }

        return platform.version
      })

import * as core from '@actions/core'
import * as inputHelper from './input-helper'
import * as dockerhubHelper from './dockerhub-helper'
import * as readmeHelper from './readme-helper'
import * as utils from './utils'
import {inspect} from 'util'

const SHORT_DESCRIPTION_MAX_BYTES = 100

async function run(): Promise<void> {
  try {
    const inputs = inputHelper.getInputs()
    core.debug(`Inputs: ${inspect(inputs)}`)

    inputHelper.validateInputs(inputs)

    // Fetch the readme content
    core.info('Reading description source file')
    const readmeContent = await readmeHelper.getReadmeContent(
      inputs.readmeFilepath,
      inputs.enableUrlCompletion,
      inputs.imageExtensions
    )
    core.debug(readmeContent)

    // Truncate the short description if it is too long
    const truncatedShortDescription = utils.truncateToBytes(
      inputs.shortDescription,
      SHORT_DESCRIPTION_MAX_BYTES
    )
    if (truncatedShortDescription.length !== inputs.shortDescription.length) {
      core.warning(
        `The short description exceeds DockerHub's limit and has been truncated to ${SHORT_DESCRIPTION_MAX_BYTES} bytes.`
      )
    }
    core.debug(`Truncated short description: ${truncatedShortDescription}`)

    // Acquire a token for the Docker Hub API
    core.info('Acquiring token')
    const token = await dockerhubHelper.getToken(
      inputs.username,
      inputs.password
    )
    // Send a PATCH request to update the description of the repository
    core.info('Sending PATCH request')
    await dockerhubHelper.updateRepositoryDescription(
      token,
      inputs.repository,
      truncatedShortDescription,
      readmeContent
    )
    core.info('Request successful')
  } catch (error) {
    core.debug(inspect(error))
    core.setFailed(utils.getErrorMessage(error))
  }
}

